from sqlglot import maybe_parse, exp
from sqlglot.schema import ensure_schema
from sqlglot.optimizer import build_scope, qualify

def mk(sql, schema=None, dialect=None):
    e = maybe_parse(sql, dialect=dialect)
    s = ensure_schema(schema or {}, dialect=dialect)
    e = qualify.qualify(e, dialect=dialect, schema=s, validate_qualify_columns=False, identify=False)
    return build_scope(e), s

def show(scope, indent=0):
    print(" "*indent, type(scope.expression).__name__, scope.scope_type, repr(scope.expression.sql())[:80])
    for s in scope.subquery_scopes:
        print(" "*indent, " SUBQUERY->")
        show(s, indent+4)
    for k,v in scope.sources.items():
        if hasattr(v, 'expression'):
            print(" "*indent, f" SRC {k!r}->")
            show(v, indent+4)

cands = [
 "(SELECT a FROM (SELECT a FROM x) AS s)",
 "(SELECT a FROM x WHERE a IN (SELECT a FROM y))",
 "SELECT a FROM (SELECT a FROM x UNION SELECT a FROM y)",
 "SELECT a FROM x, LATERAL (SELECT a FROM y)",
 "SELECT a FROM UNNEST([1,2]) AS a",
]
for sql in cands:
    print("=====", sql)
    try:
        scope, schema = mk(sql)
        show(scope)
    except Exception as e:
        print("ERR", type(e).__name__, e)
EOF"}

