{"command": "cd /testbed; python - <<'EOF'
from sqlglot.lineage import lineage
sql = "SELECT * FROM (SELECT * FROM monthly_sales PIVOT(SUM(amount) FOR month IN ('JAN', 'FEB')) ) AS p"
node = lineage("JAN", sql, dialect="bigquery", schema={"monthly_sales": {"amount": "int", "month": "text"}})
def show(n, i=0):
    print(" "*i, n.name, "|", n.expression.sql(dialect="bigquery")[:70], "|", n.source.sql(dialect="bigquery")[:60])
    for d in n.downstream:
        show(d, i+2)
show(node)
EOF"}

